package store

import (
	"bytes"
	"encoding/base64"
	"encoding/json"
	"errors"
)

// Cursor marks a pagination position: (instant, tie-break key).
type Cursor struct {
	TS  int64  `json:"t"`
	Key string `json:"k"`
}

// ErrBadCursor signals a cursor not generated by the bridge or tampered with.
var ErrBadCursor = errors.New("invalid cursor")

const (
	maxCursorLen    = 512
	maxCursorKeyLen = 256
)

// EncodeCursor serializes the cursor as base64url JSON (opaque to the Worker).
func EncodeCursor(c Cursor) string {
	raw, _ := json.Marshal(c)
	return base64.RawURLEncoding.EncodeToString(raw)
}

// DecodeCursor validates and decodes a cursor; "" returns nil without error.
func DecodeCursor(s string) (*Cursor, error) {
	if s == "" {
		return nil, nil
	}
	if len(s) > maxCursorLen {
		return nil, ErrBadCursor
	}
	raw, err := base64.RawURLEncoding.DecodeString(s)
	if err != nil {
		return nil, ErrBadCursor
	}
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	var c Cursor
	if err := dec.Decode(&c); err != nil || dec.More() || !validCursor(c) {
		return nil, ErrBadCursor
	}
	return &c, nil
}

// validCursor checks ranges and key length.
func validCursor(c Cursor) bool {
	return c.TS >= 0 && c.Key != "" && len(c.Key) <= maxCursorKeyLen
}
